import os
from google import genai
from google.genai import types

client = genai.Client(api_key=os.environ["GEMINI_API_KEY"])

def inspect_postgres_lock(tenant_id: str) -> dict:
    """Custom tool truy van pg_stat_activity va trang thai khoa dong cho tenant."""
    return {"tenant_id": tenant_id, "blocked_queries": 3, "lock_wait_ms": 4820}

def run_shell_diagnostic(cmd: str) -> str:
    """Custom bash tool chi cho phep doc log container an toan."""
    return f"[READONLY_EXEC] {cmd} -> worker_pool=saturated"

def scout_with_gemini_customtools(incident_brief: str) -> str:
    # Su dung bien the -customtools toi uu cho phoi hop bash + custom tool
    response = client.models.generate_content(
        model="gemini-3.1-pro-preview-customtools",
        contents=incident_brief,
        config=types.GenerateContentConfig(
            thinking_config=types.ThinkingConfig(thinking_level="high"),
            tools=[inspect_postgres_lock, run_shell_diagnostic],
            max_output_tokens=16384,
        ),
    )
    return response.text

def select_escalation_model(evidence_tokens: int) -> dict:
    """Chot chan FinOps tranh vach da 272K (2x input / 1.5x output) cua GPT-5.6."""
    if evidence_tokens <= 265000:
        return {
            "provider": "openai",
            "model": "gpt-5.6-sol",
            "reasoning_effort": "xhigh",
            "note": "Nam duoi nguong 272K: don gia chuan $4/$20",
        }
    # Vuot 272K: tranh phi phat 2x/1.5x cua GPT-5.6 -> chuyen sang Fable 5.2 + 1h Cache Read $0.20
    return {
        "provider": "anthropic",
        "model": "claude-fable-5-2",
        "effort": "max",
        "cache_ttl": "1h",
        "note": "Fable 5.2 khong bi nhan he so >272K va Cache Read chi $0.20/1M",
    }
